/**
 * Documentation generated by Gemini
 * Purpose: Provides a form for campsite owners to configure and publish lottery listing pools linked to campsites.
 * Role / Design Pattern: View layer Composable screen in MVVM architecture managing owner lottery setup.
 * Outstanding Issues: Date picker components currently use text input fields.
 */
package com.example.campsitelottery

import android.util.Log
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.verticalScroll
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.RectangleShape
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import androidx.navigation.NavController
import com.google.firebase.firestore.FirebaseFirestore
import java.text.SimpleDateFormat
import java.util.*
import androidx.compose.ui.platform.LocalLocale
import kotlinx.coroutines.tasks.await

/**
 * Composable screen allowing a campsite owner to create and publish a new lottery waitlist.
 *
 * @param navController Navigation controller for routing back to the dashboard.
 */
@Composable
fun CreateLotteryScreen(
    navController: NavController,
    deviceId: String,
    waitlistId: String? = null
) {

    val isEditing = waitlistId != null

    var ownerCampsites by remember { mutableStateOf(listOf<Campsite>()) }
    var selectedCampsiteIds by remember { mutableStateOf(setOf<String>()) }
    var lotteryName by remember { mutableStateOf("") }

    var regStartStr by remember { mutableStateOf("") }
    var regEndStr by remember { mutableStateOf("") }
    var bookStartStr by remember { mutableStateOf("") }
    var bookEndStr by remember { mutableStateOf("") }
    var numberOfWinners by remember { mutableStateOf("") }
    var maxCapacity by remember { mutableStateOf("") }


    val scrollState = rememberScrollState()




    // Fetch the owner's registered campsites from Firestore
    LaunchedEffect(deviceId) {
        FirebaseFirestore.getInstance().collection("campsites")
            .whereEqualTo("ownerId", deviceId)
            .get()
            .addOnSuccessListener { snapshot ->
                ownerCampsites = snapshot.documents.mapNotNull { it.toObject(Campsite::class.java) }
            }
    }

    LaunchedEffect(waitlistId) {
        if (waitlistId == null) return@LaunchedEffect
        try {
            val wl = FirebaseFirestore.getInstance()
                .collection("waitlists").document(waitlistId)
                .get().await()
                .toObject(Waitlist::class.java) ?: return@LaunchedEffect

            selectedCampsiteIds = wl.campsiteIds.toSet()
            lotteryName = wl.lotteryName
            regStartStr = wl.registrationStartDate?.let { dateISOFormat().format(it) } ?: ""
            regEndStr = wl.registrationEndDate?.let { dateISOFormat().format(it) } ?: ""
            bookStartStr = wl.bookingStartDate?.let { dateISOFormat().format(it) } ?: ""
            bookEndStr = wl.bookingEndDate?.let { dateISOFormat().format(it) } ?: ""
            numberOfWinners = wl.numberOfWinnersToDraw.toString()
            maxCapacity = wl.maxWaitlistCapacity?.toString() ?: ""
        } catch (e: Exception) {
            Log.e("CreateLottery", "Failed to load lottery", e)
        }
    }


    Column(
        modifier = Modifier
            .fillMaxSize()
            .statusBarsPadding()
            .imePadding()
            .padding(16.dp)
    ) {
        Button(onClick = { navController.popBackStack() }, shape = RectangleShape) {
            Text("Back")
        }

        Spacer(modifier = Modifier.height(16.dp))
        Text(text = if(isEditing) "Edit Campsite Lottery" else "Create Campsite Lottery", fontSize = 24.sp)
        Spacer(modifier = Modifier.height(16.dp))

        Column(
            modifier = Modifier
                .fillMaxWidth()
                .weight(1f)
                .verticalScroll(scrollState),
            verticalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            if (!isEditing){
                Text(text = "Select Campsite(s) for Lottery:", fontSize = 16.sp)

                if (ownerCampsites.isEmpty()) {
                    Text(text = "You must register a campsite first before creating a lottery.")
                } else {
                    ownerCampsites.forEach { campsite ->
                        val isSelected = selectedCampsiteIds.contains(campsite.campsiteId)
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Checkbox(
                                checked = isSelected,
                                onCheckedChange = { checked ->
                                    selectedCampsiteIds = if (checked) {
                                        selectedCampsiteIds + campsite.campsiteId
                                    } else {
                                        selectedCampsiteIds - campsite.campsiteId
                                    }
                                }
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Text(text = "${campsite.name} (${campsite.address})")
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.height(8.dp))
            OutlinedTextField(
                value = lotteryName,
                onValueChange = { lotteryName = it },
                label = { Text("Lottery Name / Title (e.g., Summer Group Draw)") },
                modifier = Modifier.fillMaxWidth()
            )

            OutlinedTextField(
                value = regStartStr,
                onValueChange = { regStartStr = it },
                label = { Text("Registration Start Date (yyyy-MM-dd)") },
                modifier = Modifier.fillMaxWidth()
            )

            OutlinedTextField(
                value = regEndStr,
                onValueChange = { regEndStr = it },
                label = { Text("Registration End Date (yyyy-MM-dd)") },
                modifier = Modifier.fillMaxWidth()
            )

            OutlinedTextField(
                value = bookStartStr,
                onValueChange = { bookStartStr = it },
                label = { Text("Booking Start Date (yyyy-MM-dd)") },
                modifier = Modifier.fillMaxWidth()
            )

            OutlinedTextField(
                value = bookEndStr,
                onValueChange = { bookEndStr = it },
                label = { Text("Booking End Date (yyyy-MM-dd)") },
                modifier = Modifier.fillMaxWidth()
            )

            OutlinedTextField(
                value = numberOfWinners,
                onValueChange = { numberOfWinners = it },
                label = { Text("Number of Winners to Draw") },
                modifier = Modifier.fillMaxWidth()
            )

            OutlinedTextField(
                value = maxCapacity,
                onValueChange = { maxCapacity = it },
                label = { Text("Max Waitlist Capacity (Optional)") },
                modifier = Modifier.fillMaxWidth()
            )
        }

        Spacer(modifier = Modifier.height(8.dp))

        Button(
            onClick = {
                try {



                    val regStart = dateISOFormat().parse(regStartStr)
                    val regEnd = dateISOFormat().parse(regEndStr)
                    val bookStart = dateISOFormat().parse(bookStartStr)
                    val bookEnd = dateISOFormat().parse(bookEndStr)
                    val winnersCount = numberOfWinners.toIntOrNull() ?: 1
                    val capacity = maxCapacity.toIntOrNull()

                    val db = FirebaseFirestore.getInstance()

                    if (waitlistId != null) {
                        // winners, and isDrawn are left untouched
                        db.collection("waitlists").document(waitlistId)
                            .update(
                                mapOf(
                                    "campsiteIds" to selectedCampsiteIds.toList(),
                                    "lotteryName" to lotteryName.ifBlank { "Campsite Lottery" },
                                    "registrationStartDate" to regStart,
                                    "registrationEndDate" to regEnd,
                                    "bookingStartDate" to bookStart,
                                    "bookingEndDate" to bookEnd,
                                    "numberOfWinnersToDraw" to winnersCount,
                                    "maxWaitlistCapacity" to capacity
                                )
                            )
                            .addOnSuccessListener { navController.popBackStack() }
                            .addOnFailureListener { e ->
                                Log.e("EditLottery", "Failed to save lottery", e)
                            }
                    } else {
                        val newWaitlist = Waitlist(
                            campsiteIds = selectedCampsiteIds.toList(),
                            ownerId = deviceId,
                            lotteryName = lotteryName.ifBlank { "Campsite Lottery" },
                            registrationStartDate = regStart,
                            registrationEndDate = regEnd,
                            bookingStartDate = bookStart,
                            bookingEndDate = bookEnd,
                            numberOfWinnersToDraw = winnersCount,
                            maxWaitlistCapacity = capacity,
                            isDrawn = false
                        )

                        db.collection("waitlists").add(newWaitlist)
                            .addOnSuccessListener { navController.popBackStack() }
                            .addOnFailureListener { e ->
                                Log.e("CreateLottery", "Failed to save lottery", e)
                            }
                    }

                } catch (e: Exception) {
                    // Handle parsing errors
                    Log.e("CreateLottery", "Failed to parse input", e)
                }
            },
            shape = RectangleShape,
            modifier = Modifier.fillMaxWidth(),
            enabled = selectedCampsiteIds.isNotEmpty()
        ) {
            Text(if (waitlistId != null) "Save Changes" else "Publish Lottery Listing")
        }
    }
}
